"""Flat-file (JSON) storage layer for tasks. No database engine is used —
all data lives in a single JSON file on disk, guarded by an in-process lock
plus atomic write-and-replace to avoid partial/corrupt writes."""

import json
import os
import threading
from datetime import datetime

_lock = threading.Lock()

DEFAULT_FILE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "data", "tasks.json"
)


def get_storage_file():
    return os.environ.get("TASKS_FILE", DEFAULT_FILE)


def init_storage():
    path = get_storage_file()
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    if not os.path.exists(path):
        _write({"next_id": 1, "tasks": []})


def _read():
    path = get_storage_file()
    with open(path, "r") as f:
        return json.load(f)


def _write(data):
    path = get_storage_file()
    tmp_path = f"{path}.tmp"
    with open(tmp_path, "w") as f:
        json.dump(data, f, indent=2)
    os.replace(tmp_path, path)


def create_task(title):
    with _lock:
        data = _read()
        task = {
            "id": data["next_id"],
            "title": title,
            "status": "pending",
            "created_at": datetime.utcnow().isoformat(),
        }
        data["tasks"].append(task)
        data["next_id"] += 1
        _write(data)
        return task


def list_tasks():
    data = _read()
    return sorted(data["tasks"], key=lambda t: (t["created_at"], t["id"]), reverse=True)


def get_task(task_id):
    data = _read()
    for task in data["tasks"]:
        if task["id"] == task_id:
            return task
    return None


def update_task(task_id, title=None, status=None):
    with _lock:
        data = _read()
        for task in data["tasks"]:
            if task["id"] == task_id:
                if title is not None:
                    task["title"] = title
                if status is not None:
                    task["status"] = status
                _write(data)
                return task
        return None

"""Flask API for task management.

Storage is flat-file (JSON), not a database — see storage.py.
"""

from flask import Flask, jsonify, request

import storage


def create_app():
    app = Flask(__name__)
    storage.init_storage()

    @app.errorhandler(404)
    def not_found(_e):
        return jsonify({"error": "Not found"}), 404

    @app.errorhandler(405)
    def method_not_allowed(_e):
        return jsonify({"error": "Method not allowed"}), 405

    @app.route("/tasks", methods=["POST"])
    def create_task():
        data = request.get_json(silent=True) or {}
        title = data.get("title")
        if not isinstance(title, str) or not title.strip():
            return jsonify({"error": "title is required"}), 400
        task = storage.create_task(title.strip())
        return jsonify(task), 201

    @app.route("/tasks", methods=["GET"])
    def list_tasks():
        return jsonify(storage.list_tasks()), 200

    @app.route("/tasks/<int:task_id>", methods=["GET"])
    def get_task(task_id):
        task = storage.get_task(task_id)
        if task is None:
            return jsonify({"error": "Task not found"}), 404
        return jsonify(task), 200

    @app.route("/tasks/<int:task_id>", methods=["PUT"])
    def update_task(task_id):
        if storage.get_task(task_id) is None:
            return jsonify({"error": "Task not found"}), 404

        data = request.get_json(silent=True) or {}
        has_title = "title" in data
        has_status = "status" in data
        if not has_title and not has_status:
            return jsonify({"error": "title or status is required"}), 400

        title = data.get("title")
        if has_title and (not isinstance(title, str) or not title.strip()):
            return jsonify({"error": "title must be a non-empty string"}), 400

        status = data.get("status")
        if has_status and (not isinstance(status, str) or not status.strip()):
            return jsonify({"error": "status must be a non-empty string"}), 400

        task = storage.update_task(
            task_id,
            title=title.strip() if has_title else None,
            status=status.strip() if has_status else None,
        )
        return jsonify(task), 200

    return app


app = create_app()

if __name__ == "__main__":
    app.run(debug=True)
